const s=[{id:"identity-gollwitzer",title:"I01 · Gollwitzer e Sheeran · 2006 · Piani “se succede questo, farò quello” e obiettivi",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"In 94 verifiche indipendenti con 8.461 partecipanti, questi piani favorivano in media il raggiungimento degli obiettivi (d = 0,65).",limitation:"Le 83 verifiche sperimentali e 11 correlazionali riguardavano obiettivi e metodi diversi. Non convalidano un pacchetto commerciale sulle abitudini o questo specifico piano ODA."},{id:"identity-harkin",title:"I02 · Harkin e colleghi · 2016 · Monitorare i progressi verso gli obiettivi",url:"https://doi.org/10.1037/bul0000025",type:"research",finding:"In 138 studi randomizzati, gli interventi di monitoraggio miglioravano in media il raggiungimento degli obiettivi (d = 0,40). La stima corretta per le distorsioni era più piccola (d = 0,19).",limitation:"Obiettivi e modi di annotare erano diversi. I risultati sui fattori che modificano gli effetti non impongono di condividere pubblicamente. Questo riepilogo e la revisione del giorno dopo non sono stati verificati."},{id:"identity-cole",title:"I03 · Cole e colleghi · 2021 · Simulazione mentale e cambiamento del comportamento",url:"https://doi.org/10.3758/s13423-021-01880-6",type:"research",finding:"In 94 studi randomizzati, la simulazione mentale mostrava un effetto medio sul comportamento (g = 0,49). Il confronto complessivo fra i tipi di simulazione non era statisticamente significativo.",limitation:"I campioni erano soprattutto studenti; descrizioni incomplete e sottogruppi piccoli limitano la certezza. Non emerge un tipo di immaginazione migliore, né un effetto della meditazione sull’identità."},{id:"identity-lally",title:"I04 · Lally e colleghi · 2010 · Come si formano le abitudini?",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"Nei 39 modelli con buona corrispondenza ai dati, il tempo stimato per arrivare al 95% del livello stabile di automaticità aveva mediana 66 giorni e intervallo 18-254 giorni.",limitation:"Iniziarono 96 volontari; i comportamenti furono osservati per 84 giorni. Le stime più lunghe erano estrapolate. Non era una scadenza per cambiare identità né una verifica della regola sui due giorni saltati."},{id:"identity-habit-times",title:"I05 · Singh e colleghi · 2024 · Rassegna sulla formazione delle abitudini",url:"https://doi.org/10.3390/healthcare12232488",type:"research",finding:"Una rassegna di 20 studi sui comportamenti per la salute trovava grandi differenze nella formazione delle abitudini. Solo quattro studi riportavano i tempi necessari.",limitation:"11 studi avevano alto rischio di distorsione. Il miglioramento dei punteggi prima e dopo non è un effetto causale randomizzato. Non emerge una scadenza universale per formare un’abitudine."},{id:"identity-wood-runger",title:"I06 · Wood e Rünger · 2016 · Psicologia dell’abitudine",url:"https://doi.org/10.1146/annurev-psych-122414-033417",type:"research",finding:"La rassegna descrive abitudini che si sviluppano ripetendo risposte in contesti ricorrenti. I processi abituali e quelli consapevoli possono operare insieme.",limitation:"È una rassegna narrativa, senza effetto medio aggregato. Non classifica ogni umore o pensiero come abitudine né dimostra che cambiare contesto sia sempre superiore all’impegno."},{id:"identity-wood-everyday",title:"I07 · Wood, Quinn e Kashy · 2002 · Le abitudini nella vita quotidiana",url:"https://doi.org/10.1037/0022-3514.83.6.1281",type:"research",finding:"In due gruppi di studenti che compilavano diari, il 35% e il 43% dei comportamenti riferiti rispondeva alla definizione di abitudine: quasi ogni giorno, nello stesso luogo.",limitation:"I campioni comprendevano 70 e 209 studenti. Le percentuali non stimano tutta la popolazione né quanto spesso la mente vaga. I diari non verificavano un intervento sull’identità."},{id:"identity-lieberman",title:"I10 · Lieberman e colleghi · 2007 · Dare parole alle emozioni",url:"https://doi.org/10.1111/j.1467-9280.2007.01916.x",type:"research",finding:"In 30 adulti che guardavano volti, scegliere parole emotive produceva minore attivazione dell’amigdala rispetto a scegliere nomi corrispondenti al genere.",limitation:"È un piccolo studio di neuroimmagine in laboratorio, non una misura del recupero emotivo quotidiano. Non dimostra che nominare il proprio disagio lo riduca."},{id:"identity-breines",title:"I11 · Breines e Chen · 2012 · Compassione verso di sé e voglia di migliorare",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Quattro brevi esperimenti sostenevano la motivazione immediata a migliorarsi dopo risposte con compassione verso di sé. In un esperimento si studiava più a lungo rispetto al gruppo senza intervento.",limitation:"Campioni soprattutto di studenti e partecipanti reclutati online; gli effetti cambiavano secondo il confronto. In quello studio i punteggi del test non differivano significativamente. Non fu dimostrato un cambiamento duraturo dell’identità."},{id:"identity-clear-identity",title:"I15 · James Clear · Abitudini basate sull’identità",url:"https://jamesclear.com/identity-based-habits",type:"technique",finding:"Clear propone piccoli gesti come elementi a sostegno dell’identità desiderata. L’azione come “voto” è una metafora proposta dall’autore.",limitation:"L’articolo non è un esperimento e l’anno di pubblicazione non è accertato. La superiorità del cambiare prima identità e la regola “mai saltare due volte” non sono leggi scientifiche verificate."},{id:"identity-task-belief",title:"I17 · Bandura · 1977 · Teoria dell’autoefficacia",url:"https://doi.org/10.1037/0033-295X.84.2.191",type:"research",finding:"Il modello descrive la capacità percepita in un compito preciso, alimentata da padronanza, osservazione degli altri, persuasione e informazioni fisiologiche.",limitation:"È una sintesi teorica, non una stima aggregata di interventi. Le convinzioni sulle capacità non misurano il valore personale né verificano il metodo dei “voti” per l’identità."},{id:"identity-activity-identity",title:"I19 · Rhodes e colleghi · 2025 · Interventi sull’identità legata all’attività fisica",url:"https://doi.org/10.1080/17437199.2024.2412996",type:"research",finding:"In 40 effetti sperimentali o quasi sperimentali con 4.939 adulti, l’identità legata all’attività fisica cambiava poco in media (g = 0,18).",limitation:"Gli effetti sul comportamento venivano da un diverso sottogruppo di 30 effetti ed erano eterogenei. La rassegna non dimostra che l’identità causasse il cambiamento dei gesti né si estende alla trasformazione dell’intera persona."},{id:"identity-motor-rehearsal",title:"I18 · Toth e colleghi · 2020 · Pratica mentale e prestazioni nei compiti",url:"https://doi.org/10.1016/j.psychsport.2020.101672",type:"research",finding:"La rassegna di 37 studi riportava un piccolo effetto della pratica mentale, corretto per le distorsioni, sulle prestazioni motorie o nei compiti (r = 0,131).",limitation:"L’abstract consultato non accertava il totale dei partecipanti o l’intervallo di confidenza. I dati motori non dimostrano cambiamento d’identità, guarigione o effetti sulla biologia emotiva."}],a=[{schemaVersion:2,revision:2,id:"identity-1",courseId:"identity",locale:"it",title:"Ancora al telefono? Cambia un momento della giornata",goal:"Scegli un segnale che si ripete e prova una risposta utile per la tua settimana.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Un altro pomeriggio perso nella solita distrazione? Trova un momento in cui puoi fare qualcosa di diverso.",reason:{id:"identity-1-reason",label:"Che cosa ti dà questa abitudine oggi? Che cosa rimanda?",kind:"text",maxLength:160,optional:!0,suggestions:["Finire senza un’altra serata di lavoro","Fare spazio al mio lavoro creativo","Dare attenzione alle persone"]},why:{id:"identity-1-direction",label:"Perché questo passo conta nella tua settimana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Un posto familiare può farti ripetere un gesto, anche se le tue priorità sono cambiate. La ricerca sulle abitudini distingue quel gesto dalla tua personalità. “Dopo pranzo guardo il telefono prima di iniziare” descrive uno schema. “Sono una persona pigra” non ti indica dove intervenire.","Scegli un momento abituale e un’alternativa utile. Guarda che cosa ti offre subito la vecchia risposta e che cosa rimanda. Poi prova l’alternativa una volta. Nel corso migliorerai questa stessa prova. Puoi iniziare con un piccolo gesto senza rinnegare chi sei o prometterti una personalità nuova."],example:{title:"Elena scrive la prima frase",text:"Alle 13:30 Elena torna alla scrivania e prende il telefono prima di scrivere una relazione. Vuole lavorare meno la sera. Mette da parte il telefono e butta giù una frase iniziale. È poco scorrevole e più tardi riprende il telefono. Annota che cosa ha fatto in quel momento, senza chiamare quel pomeriggio una trasformazione."}},move:{invitation:"Scegli un momento abituale. Prova una risposta utile per ciò che conta per te.",instructions:["Indica il segnale di inizio e il gesto concreto che proverai.","Annota che cosa hai fatto quando si è presentato quel segnale."],prompts:[],suggestions:{action:["Scrivere una frase da usare","Fare una domanda con attenzione","Completare un piccolo passo concreto"],minimum:["Aggiungere una frase alla mia bozza","Ascoltare una risposta fino alla fine","Finire una parte utile"],cue:["Quando torno dopo pranzo","Quando poso la borsa","Quando comincio la mia attività serale"],place:["Alla mia solita postazione","Dove possiamo parlare in sicurezza"],fallback:["Dettare la frase invece di scriverla","Usare il prossimo segnale disponibile","Chiedere un aiuto concreto"],observation:["Se ho scritto la frase","Che cosa ho fatto al segnale","Che cosa ha rimandato la vecchia risposta"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},suggested:{action:"Scrivere una frase da usare",minimum:"Aggiungere una frase alla mia bozza",minutes:2,cueHint:"Quando torno dopo pranzo",placeHint:"Alla mia solita postazione",obstacleHint:"La solita distrazione è più a portata di mano.",fallbackHint:"Dettare la frase invece di scriverla",observationHint:"Se ho scritto la frase"},stopRule:"Se ci sono pericolo o maltrattamenti, scegli di proteggerti o chiedere sostegno.",accessibleAlternative:"Scrivi, detta, fatti aiutare o scegli un’azione equivalente e accessibile."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto e che cosa è successo dopo?"},judgment:{primary:{id:"identity-1-decision",scenario:"Elena voleva scrivere dopo pranzo, ma ha guardato il telefono. Ha cinque minuti e la relazione aperta.",question:"Quale passo avvia una prova utile?",options:[{id:"identity-1-redesign-day",text:"Preparare un programma pomeridiano più rigido e iniziare la relazione solo dopo aver completato il nuovo programma.",feedback:"Un programma potrà aiutare. Adesso aggiunge preparazione prima di una prova già possibile. Individua il momento dopo pranzo, scrivi una frase utile e annota che cosa ti ostacola."},{id:"identity-1-test-cue",text:"Descrivere che cosa è successo dopo pranzo, poi scrivere una frase della relazione e annotare il segnale.",feedback:"Così provi una risposta nel suo contesto. La frase fa avanzare il lavoro e la nota identifica il segnale. Una prova dà informazioni senza dimostrare un cambiamento di personalità."},{id:"identity-1-change-break",text:"Spostare la scrittura di domani prima di pranzo e usare i cinque minuti rimasti per rivedere il piano.",feedback:"Cambiare segnale può aiutare se il problema è l’orario del pranzo. Qui puoi ancora provare per cinque minuti. Scrivi una frase e annota il segnale prima di scegliere un altro programma."}],bestOptionId:"identity-1-test-cue"}},carry:{takeaway:"Cambia una risposta in un contesto. Annota quello che è successo.",followUp:{questionId:"identity-1-return",question:"Quando è arrivato il segnale scelto, che cosa hai fatto al posto della solita risposta?",observationPrompt:"Indica la risposta al segnale, oppure annota che quel momento non si è presentato.",adjustmentPrompt:"Che cosa vuoi mantenere, cambiare o interrompere alla prossima prova?"}},goDeeper:{sections:[{heading:"Uno schema non descrive tutta una persona",paragraphs:["La rassegna di Wood e Rünger descrive le abitudini come risposte ripetute associate a contesti ricorrenti [I06]. Un ambiente può richiamare una risposta familiare, insieme alle scelte consapevoli. È un’affermazione più limitata rispetto a dire che ogni pensiero, umore o giornata difficile segue un programma automatico. Questa lezione guarda un comportamento osservabile, senza chiederti di eliminare un “vecchio io”.","La ricerca basata sui diari usava gruppi di 70 e 209 studenti [I07]. Rispettivamente, il 35% e il 43% dei comportamenti descritti avveniva quasi ogni giorno nello stesso luogo: questa era la definizione di abitudine. Le percentuali non rappresentano tutti gli adulti né il tempo trascorso con la mente altrove. Osservare il comportamento serviva a valutarlo, non era un trattamento dimostrato per cambiare identità.","La nota di ODA sul segnale e sulla risposta è un adattamento per imparare. Conserva i dettagli utili alla prossima scelta. Un umore invariato o un pomeriggio imperfetto non cancellano una prova descritta con precisione."]},{heading:"L’alternativa deve servire a qualcosa",paragraphs:["Gollwitzer e Sheeran hanno riunito 94 verifiche indipendenti con 8.461 partecipanti [I01]. I piani specifici “se succede questo, farò quello” favorivano in media il raggiungimento degli obiettivi. La ricerca comprendeva 83 verifiche sperimentali e 11 correlazionali, con obiettivi e metodi diversi. Non dimostra che questa particolare sequenza di ODA cambi l’identità.","In questa prova abbina un evento riconoscibile a una risposta fattibile: quando torni dopo pranzo, scrivi una frase utile della relazione. Scegli un segnale che incontri davvero. L’alternativa deve contribuire a ciò che vuoi fare, oltre ad aprire un’app o sistemare il materiale. Anche quelli possono essere preparativi utili, purché li descrivi come tali.","Non devi interrompere ogni comportamento abituale. Mantieni le routine che ti aiutano a vivere. Se il contesto richiede protezione, riposo o aiuto, scegli quella risposta consapevolmente. Guarda com’è andata questa prova prima di aggiungere un altro sistema."]}],sourceIds:["identity-wood-runger","identity-wood-everyday","identity-gollwitzer"]}},{schemaVersion:2,revision:2,id:"identity-2",courseId:"identity",locale:"it",title:"La preoccupazione resta? Puoi scegliere come rispondere",goal:"Al segnale già scelto, fai il gesto utile anche se una normale emozione resta.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Aspetti che la preoccupazione passi prima di iniziare? Dai una possibilità sicura al gesto che hai scelto.",reason:{id:"identity-2-reason",label:"Che cosa rimandi mentre aspetti che questa emozione passi?",kind:"text",maxLength:160,optional:!0,suggestions:["Iniziare anche con una normale preoccupazione","Proteggere una serata a cui tengo","Rispondere senza nascondere i miei bisogni"]},why:{id:"identity-2-direction",label:"Perché questo passo conta nella tua settimana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Riprendi il segnale e il gesto scelti. Un’emozione familiare merita attenzione, ma non dimostra una personalità immutabile. La ricerca sul dare un nome alle emozioni è limitata: un piccolo studio ha trovato una diversa risposta cerebrale quando le persone davano un nome alle emozioni espresse dai volti. Non ha verificato se la tua preoccupazione sparisce.","Usa il nome per descrivere: “Sento preoccupazione”. Controlla se indica un bisogno reale, poi scegli come rispondere. Puoi scrivere la frase anche con la preoccupazione, oppure chiedere aiuto se c’è un problema da affrontare. Il gesto utile conta anche se dopo non ti senti più calmo."],example:{title:"Elena comincia con la preoccupazione",text:"Giovedì, dopo pranzo, Elena è preoccupata per la stessa relazione. Controlla di avere i dati necessari, dà un nome alla preoccupazione e scrive un’altra frase utile. Vorrebbe ancora ricontrollare tutto. Annota la frase e l’emozione rimasta. Si è esercitata a scrivere; non ha dimostrato che quell’emozione sia un’abitudine."}},move:{invitation:"Continua la prova. Se serve, nomina un’emozione normale, poi fai il gesto scelto.",instructions:["Verifica se c’è un problema concreto prima di considerarla una normale preoccupazione.","Prova anche se l’emozione resta."],prompts:[],suggestions:{action:["Scrivere un’altra frase utile","Ascoltare anche con un normale senso di colpa","Chiedere l’aiuto di cui ho bisogno"],minimum:["Aggiungere una frase alla mia bozza","Fare una domanda con attenzione","Inviare una richiesta di aiuto concreto"],cue:["Quando mi preoccupo al segnale scelto","Dopo aver verificato il bisogno urgente","Alla prossima occasione sicura"],place:["Alla mia solita postazione","In uno spazio condiviso sicuro"],fallback:["Dettare una frase utile","Affrontare prima il problema concreto","Chiedere invece sostegno"],observation:["Se ho agito con la preoccupazione","Se c’era un bisogno reale non soddisfatto","La richiesta o la risposta che ho dato"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},suggested:{action:"Scrivere un’altra frase utile",minimum:"Aggiungere una frase alla mia bozza",minutes:2,cueHint:"Quando mi preoccupo al segnale scelto",placeHint:"Alla mia solita postazione",obstacleHint:"Vorrei che l’emozione sparisse prima di agire.",fallbackHint:"Dettare una frase utile",observationHint:"Se ho agito con la preoccupazione"},stopRule:"Se ci sono pericolo o maltrattamenti, scegli di proteggerti o chiedere sostegno.",accessibleAlternative:"Scrivi, detta, fatti aiutare o scegli un’azione equivalente e accessibile."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto e che cosa è successo dopo?"},judgment:{primary:{id:"identity-2-decision",scenario:"Elena ha cinque minuti. I dati corrispondono alla tabella approvata; la frase non richiede nuovi calcoli. È ancora preoccupata.",question:"Quale risposta è adatta a questo momento?",options:[{id:"identity-2-recheck",text:"Ricontrollare i dati un’altra volta per sentirsi più sicura prima di scrivere la frase.",feedback:"Un altro controllo aiuta quando mancano informazioni. Qui i dati necessari sono già verificati. Ricontrollarli rinvia la scrittura; sentirsi più calma non diventa per questo un segnale di inizio affidabile."},{id:"identity-2-provisional-check",text:"Scrivere una frase provvisoria e chiedere a un collega di verificarne il dato prima di lasciarla nella relazione.",feedback:"Una frase provvisoria e un secondo controllo aiutano se il dato è incerto. Qui la tabella approvata lo conferma. Aspettare un’altra risposta ritarda una frase utile senza affrontare una lacuna conosciuta."},{id:"identity-2-act-with-feeling",text:"Dare un nome alla preoccupazione, scrivere una frase utile e annotare se il problema richiedeva altre azioni.",feedback:"Così riconosce l’emozione e ne verifica il significato, senza lasciarle bloccare automaticamente il gesto. La frase è l’esercizio concreto. Se emerge un problema reale, potrà chiedere un aiuto pratico."}],bestOptionId:"identity-2-act-with-feeling"}},carry:{takeaway:"Un’emozione può restare mentre scegli una risposta utile e sicura.",followUp:{questionId:"identity-2-return",question:"L’emozione è rimasta durante il gesto? Indicava un bisogno reale non soddisfatto?",observationPrompt:"Indica l’emozione rimasta e il bisogno emerso, oppure annota che non c’era un bisogno chiaro.",adjustmentPrompt:"Che cosa vuoi mantenere, cambiare o interrompere alla prossima prova?"}},goDeeper:{sections:[{heading:"Che cosa misurava lo studio sulle emozioni",paragraphs:["Lieberman e colleghi hanno studiato 30 adulti sani che guardavano volti emotivi durante una scansione cerebrale [I10]. Scegliere una parola che descriveva l’emozione produceva una minore attivazione dell’amigdala rispetto a scegliere un nome corrispondente al genere del volto. È una differenza misurata in laboratorio. Non dimostra che dare un nome al proprio disagio lo riduca o migliori l’umore per settimane.","ODA propone di nominare brevemente l’emozione come descrizione facoltativa. Lo studio non ha verificato questo segnale, il tuo comportamento o un corso sull’identità. Salta il passaggio se non serve. Non trasformare ogni emozione in qualcosa da correggere. Il lutto, la rabbia per un’ingiustizia e la paura davanti al pericolo possono richiedere una risposta diversa.","Ricollega l’osservazione allo stesso gesto. L’hai fatto, ti serviva aiuto o un problema concreto ha cambiato il piano? Puoi annotare un’emozione difficile insieme a un comportamento utile senza sostenere che l’uno abbia causato l’altra."]},{heading:"Sostenerti mantenendo la responsabilità",paragraphs:["Breines e Chen hanno verificato risposte improntate alla compassione verso di sé in quattro brevi esperimenti, soprattutto con studenti o persone online [I11]. Alcuni risultati sostenevano la motivazione immediata a migliorarsi. In uno studio, dopo un test difficile i partecipanti studiavano più a lungo rispetto al gruppo senza intervento. I punteggi successivi non differivano significativamente. Il confronto con il gruppo sull’autostima non dava un risultato chiaro.","Questi risultati non dimostrano un cambiamento duraturo dell’identità né una superiorità universale della gentilezza. Mettono però in discussione l’idea che, per riprovare, serva sempre una risposta dura. Descrivere un’emozione e proseguire il gesto scelto è un adattamento ODA, diverso dall’esercizio di scrittura con compassione verso di sé studiato.","Scegli una risposta equa che mantenga visibile la tua responsabilità. Se manca una competenza, va imparata; se c’è un bisogno non soddisfatto, può servire aiuto. Puoi agire senza insultarti. Puoi fare una pausa senza trasformarla in una bocciatura della tua personalità."]}],sourceIds:["identity-lieberman","identity-breines"]}},{schemaVersion:2,revision:2,id:"identity-3",courseId:"identity",locale:"it",title:"Te ne accorgi tardi? Rendi utile il prossimo gesto",goal:"Dopo una distrazione torna al gesto scelto, oppure rimedia a una tua risposta che ha ferito qualcuno.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Stai già guardando il telefono o hai già risposto male? La prossima frase può ancora servire.",reason:{id:"identity-3-reason",label:"In questa stessa prova, a che cosa devi tornare o rimediare?",kind:"text",maxLength:160,optional:!0,suggestions:["Tornare prima di perdere il pomeriggio","Rimediare a una risposta brusca","Poter fare ancora il gesto utile"]},why:{id:"identity-3-direction",label:"Perché questo passo conta nella tua settimana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Notare una distrazione non è tornare al lavoro. Mantieni segnale e gesto. Scegli cosa fare quando te ne accorgi tardi: “Se noto che mi sono distratto, farò il mio minimo utile”. Nella ricerca, i piani specifici che collegano situazione e azione hanno favorito in media gli obiettivi.","Se una tua risposta ha ferito qualcuno, notarlo in privato non basta. In un contesto sicuro, riconosci la tua parte e riformula una frase. Se non hai ferito nessuno, torna al lavoro. Annota il gesto successivo, oltre a ciò che noti. Puoi cambiare risposta senza dichiarare rovinata la giornata."],example:{title:"Elena se ne accorge tardi",text:"Alle 13:42 Elena nota di aver passato dodici minuti al telefono invece di scrivere. Chiude i social e aggiunge una frase utile alla relazione. Più tardi rilegge un messaggio brusco inviato al collega. Manda un breve messaggio per rimediare al tono brusco. I due gesti non cancellano il tempo perso, ma sono risposte concrete che può annotare."}},move:{invitation:"Mantieni il gesto. Scegli come rispondere quando noti tardi lo schema.",instructions:["Torna al minimo utile, oppure rimedia a una tua risposta che ha fatto male.","Annota che cosa hai fatto dopo essertene accorto."],prompts:[],suggestions:{action:["Tornare alla mia frase utile","Riformulare una frase con rispetto","Rimediare al mio messaggio brusco"],minimum:["Aggiungere una frase utile adesso","Riconoscere il tono e riformulare una frase","Inviare un messaggio chiaro per rimediare"],cue:["Quando noto che guardo i social","Quando sento il mio tono brusco","Dopo la fine di un’interruzione sicura"],place:["Alla mia solita postazione","Nella conversazione scritta sicura"],fallback:["Usare una frase utile più breve","Scegliere un modo più sicuro per rimediare","Chiedere aiuto per riprendere"],observation:["Che cosa ho fatto dopo averlo notato","Se ho rimediato con un gesto concreto","Dove mi sono accorto dello schema"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},suggested:{action:"Tornare alla mia frase utile",minimum:"Aggiungere una frase utile adesso",minutes:2,cueHint:"Quando noto che guardo i social",placeHint:"Alla mia solita postazione",obstacleHint:"Me ne accorgo solo dopo che la distrazione è iniziata.",fallbackHint:"Usare una frase utile più breve",observationHint:"Che cosa ho fatto dopo averlo notato"},stopRule:"Se ci sono pericolo o maltrattamenti, scegli di proteggerti o chiedere sostegno.",accessibleAlternative:"Scrivi, detta, fatti aiutare o scegli un’azione equivalente e accessibile."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto e che cosa è successo dopo?"},judgment:{primary:{id:"identity-3-decision",scenario:"Durante una discussione sicura, Elena risponde male a un collega. Nota il suo tono mentre stanno ancora parlando.",question:"Quale gesto rende utile essersene accorta?",options:[{id:"identity-3-repair",text:"Riconoscere la frase brusca e riformulare con rispetto ciò che voleva dire, mentre la conversazione è ancora aperta.",feedback:"Così accorgersene porta a una conseguenza concreta. Elena si assume la responsabilità del tono e prova una risposta diversa. Il collega non deve perdonarla perché il tentativo di rimediare sia reale."},{id:"identity-3-private-catch",text:"Fermarsi in privato e annotare il momento, poi impegnarsi a parlare con più pazienza nella prossima discussione.",feedback:"Accorgersene dà informazioni, ma la frase brusca ha già influito sulla conversazione. Se rimediare è sicuro e appropriato, riconoscerla e riformularla affronta l’effetto attuale, oltre al comportamento di domani."},{id:"identity-3-full-explanation",text:"Spiegare che la pressione della scadenza ha causato quel tono, poi tornare al lavoro senza riparlarne.",feedback:"Il contesto può spiegare la tensione e può richiedere cambiamenti. Non sostituisce il rimediare alla propria risposta. Riconosci prima il tono, poi parla del carico di lavoro senza pretendere accordo."}],bestOptionId:"identity-3-repair"}},carry:{takeaway:"Accorgertene serve quando torni al lavoro, rimedi o scegli una risposta più sicura.",followUp:{questionId:"identity-3-return",question:"Quando hai notato lo schema? Come sei tornato al gesto o hai rimediato?",observationPrompt:"Quando l’hai notato? Sei tornato, hai rimediato, ti sei protetto o non c’era occasione?",adjustmentPrompt:"Che cosa vuoi mantenere, cambiare o interrompere alla prossima prova?"}},goDeeper:{sections:[{heading:"Puoi iniziare anche quando te ne accorgi tardi",paragraphs:["I piani “se succede questo, farò quello” collegano una situazione specifica a una risposta scelta. La sintesi di Gollwitzer e Sheeran ha trovato benefici medi sugli obiettivi in 94 verifiche indipendenti [I01]. Obiettivi, modalità e metodi erano diversi. Non convalida una particolare parola per fermarsi, una sequenza di respiri o un numero quotidiano di momenti da notare.","Qui aggiungiamo una situazione possibile: se noti di aver iniziato a guardare i social, scrivi la frase utile scelta. Continui la stessa prova del corso. Una parola detta mentalmente può essere una scorciatoia facoltativa; non è il comportamento che vuoi costruire. Per tornare al lavoro non servono un respiro particolare o una sensazione di calma.","Wood e Rünger descrivono abitudini che operano insieme alle scelte consapevoli [I06]. Puoi quindi dare una risposta intenzionale dentro una routine imperfetta. Questo non rende ogni distrazione un’abitudine. Descrivi ciò che hai osservato e verifica se riconosci quel segnale nel tuo contesto."]},{heading:"Accorgertene, poi affrontare la conseguenza",paragraphs:["Una nota dovrebbe distinguere l’accorgersi, il tornare al gesto e il rimediare. Harkin e colleghi hanno esaminato 138 studi randomizzati sul monitoraggio dei progressi [I02]. Gli interventi miglioravano in media il raggiungimento degli obiettivi, con una stima più piccola dopo la correzione per le distorsioni. Non dimostrano che contare solo ciò che noti cambi le relazioni o che ogni nota privata vada condivisa.","Per questo adattamento ODA, annota il comportamento successivo. “Ho notato il tono brusco” e “L’ho riconosciuto e ho riformulato la richiesta” sono fatti diversi. Se il lavoro si era interrotto, indica la parte utile che hai ripreso. Se non hai fatto male a nessuno, non devi scusarti.","In una relazione non sicura viene prima proteggerti. Non devi mantenere contatti, perdonare o dare spiegazioni a chi ti minaccia. Scegli un limite o un passo per chiedere sostegno, se serve. Descrivi con precisione quei gesti senza chiamare ogni pausa un rimedio riuscito."]}],sourceIds:["identity-gollwitzer","identity-wood-runger","identity-harkin"]}},{schemaVersion:2,revision:2,id:"identity-4",courseId:"identity",locale:"it",title:"Sempre a preparare? Fai un gesto che conta",goal:"Verifica che il minimo alleni ciò che serve al tuo obiettivo, poi fallo una volta.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Un altro piano perfetto, ma la bozza è vuota? Fai un gesto utile e guarda che cosa dimostra.",reason:{id:"identity-4-reason",label:"Questo minimo allena la competenza o ti fa rimandare?",kind:"text",maxLength:160,optional:!0,suggestions:["Esercitarmi facendo il lavoro","Mantenere un minimo che serva","Descrivere solo ciò che ho fatto"]},why:{id:"identity-4-direction",label:"Perché questo passo conta nella tua settimana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Riprendi l’ultima prova. James Clear chiama le azioni “voti” per un’identità. È una metafora, non una legge scientifica. Puoi usarla senza sostenere che devi cambiare identità prima di agire. La domanda utile è: questo gesto allena qualcosa che serve a ciò che vuoi fare?","Aprire una bozza dimostra che l’hai aperta. Scrivere una frase utile dimostra che hai scritto. Entrambi possono servire, ma distingui i preparativi dal lavoro svolto. Scegli un minimo abbastanza piccolo per la tua settimana e abbastanza concreto da contare. Dopo, descrivi ciò che la prova dimostra. “Ho scritto una frase” non richiede promesse di sicurezza permanente."],example:{title:"Elena sceglie un minimo utile",text:"Venerdì Elena passa cinque minuti a sistemare i titoli, senza scrivere la relazione. Riguarda la prova e sceglie come minimo una frase utile sotto un titolo. La scrive prima di fermarsi. Va ancora rivista. Nella nota facoltativa scrive “Oggi ho scritto una frase”, invece di “Adesso sono una persona disciplinata”."}},move:{invitation:"Controlla il minimo. Se prepara soltanto, chiamalo preparazione oppure scegli il gesto concreto.",instructions:["Fai una piccola parte utile del comportamento che ti serve.","Dopo, descrivi solo il gesto che hai completato."],prompts:[],suggestions:{action:["Scrivere una frase utile della relazione","Provare davvero una competenza","Usare una frase rispettosa per rimediare"],minimum:["Aggiungere una frase utile","Completare una prova concreta","Rimediare con un gesto concreto"],cue:["Quando apro la bozza già iniziata","Al mio prossimo segnale di inizio","Quando posso rimediare in sicurezza"],place:["Nella bozza su cui sto lavorando","Nel solito luogo in cui mi esercito"],fallback:["Dettare una frase utile","Ridurre la parte concreta da fare","Annotare i preparativi come preparazione"],observation:["L’azione che ho portato a termine","Se il minimo serviva al mio obiettivo","Che cosa resta da preparare"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},suggested:{action:"Scrivere una frase utile della relazione",minimum:"Aggiungere una frase utile",minutes:2,cueHint:"Quando apro la bozza già iniziata",placeHint:"Nella bozza su cui sto lavorando",obstacleHint:"Preparare sembra più facile che fare il gesto concreto.",fallbackHint:"Dettare una frase utile",observationHint:"L’azione che ho portato a termine"},stopRule:"Se ci sono pericolo o maltrattamenti, scegli di proteggerti o chiedere sostegno.",accessibleAlternative:"Scrivi, detta, fatti aiutare o scegli un’azione equivalente e accessibile."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto e che cosa è successo dopo?"},judgment:{primary:{id:"identity-4-decision",scenario:"Elena è stanca, ha cinque minuti e vuole scrivere la relazione. I titoli sono pronti; il dato della prossima frase corrisponde già alla fonte.",question:"Quale minimo serve al lavoro adesso?",options:[{id:"identity-4-organize",text:"Sistemare gli appunti in una cartella più chiara, così domani sarà più semplice cominciare a scrivere.",feedback:"Organizzarsi può aiutare la scrittura successiva. Qui appunti e titoli sono già pronti: altri preparativi rimandano la competenza che Elena vuole allenare. Se li sceglie, può registrarli come preparazione."},{id:"identity-4-write-unit",text:"Buttare giù una frase nella relazione, poi decidere se fermarsi è la scelta adatta alle sue energie.",feedback:"Questo minimo allena il comportamento desiderato e rispetta il tempo disponibile. Dimostra che ha scritto una frase, senza provare un cambiamento d’identità. Può fermarsi senza renderla brillante."},{id:"identity-4-verify-support",text:"Ricontrollare il dato citato nella fonte, poi lasciare una nota verificata per la frase di domani.",feedback:"Verificare serve quando il dato è incerto. Qui è già stato controllato: ripetere il preparativo usa il tempo per scrivere. Una frase provvisoria basata su quel dato farebbe avanzare la relazione."}],bestOptionId:"identity-4-write-unit"}},carry:{takeaway:"Descrivi l’azione che hai svolto. Distingui la preparazione dall’esercizio concreto.",followUp:{questionId:"identity-4-return",question:"Che cosa ha dimostrato il tuo minimo? Era utile per ciò che vuoi fare?",observationPrompt:"Indica l’azione che hai svolto e se ti ha aiutato nella direzione scelta.",adjustmentPrompt:"Che cosa vuoi mantenere, cambiare o interrompere alla prossima prova?"}},goDeeper:{sections:[{heading:"I limiti di una metafora sull’identità",paragraphs:["Nell’articolo di Clear, l’identità desiderata e i piccoli gesti che la sostengono sono una proposta pratica [I15]. Non è uno studio controllato che dimostri la necessità o la superiorità del cambiare prima identità. La metafora dell’azione come voto può restare facile da ricordare senza diventare una spiegazione scientifica.","Il modello di autoefficacia di Bandura riguarda quanto ti senti capace in un compito preciso [I17]. Riuscire nel compito è una fonte di questa convinzione, insieme a osservazione, persuasione e informazioni fisiologiche. Il modello non trasforma un gesto in una misura del tuo valore o in un verdetto su tutta la tua personalità.","La frase facoltativa di ODA resta circoscritta: “Ho aggiunto una frase utile” o “Ho fatto la mia richiesta”. Un piano non provato e una risposta giusta al quiz non dimostrano quei comportamenti. Puoi evitare del tutto il linguaggio sull’identità e proseguire la stessa prova concreta."]},{heading:"Comportamento e identità sono risultati diversi",paragraphs:["Rhodes e colleghi hanno esaminato 40 effetti sperimentali o quasi sperimentali con 4.939 adulti [I19]. L’identità legata all’attività fisica cambiava poco in media: g = 0,18. Un sottogruppo di 30 effetti sui comportamenti mostrava un effetto medio maggiore sull’attività, ma campioni e risultati erano diversi. Questi numeri non dimostrano che l’identità abbia causato il cambiamento del comportamento.","Gli studi riguardano l’attività fisica, con risultati eterogenei e possibile distorsione dovuta alle pubblicazioni. Non convalidano una trasformazione generale della personalità, i “voti” di Clear o questa prova di scrittura. Anche la difficoltà non dimostra automaticamente che valga la pena perseguire un obiettivo. Può indicare competenze mancanti, risorse insufficienti o la necessità di rivedere il piano.","Usa le note per capire a che cosa contribuisce il minimo. Mantieni una piccola parte se è adatta alle tue energie. Aumentala solo per scelta, oppure cambia un obiettivo inadatto. Lo scopo è esercitarti in modo utile nella tua vita, senza raccogliere voti simbolici."]}],sourceIds:["identity-clear-identity","identity-task-belief","identity-activity-identity"]}},{schemaVersion:2,revision:2,id:"identity-5",courseId:"identity",locale:"it",title:"Ancora prove mentali? Prova il gesto nella situazione reale",goal:"Se serve, preparati brevemente per un ostacolo. Poi prova lo stesso gesto nella situazione reale.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Immaginare l’inizio perfetto continua a sostituire l’inizio vero? Concludi la preparazione con una prova concreta.",reason:{id:"identity-5-reason",label:"Quale ostacolo potresti affrontare meglio con una breve prova?",kind:"text",maxLength:160,optional:!0,suggestions:["Prepararmi per il momento in cui agirò","Provare senza aspettare la frase perfetta","Distinguere la prova mentale dal gesto"]},why:{id:"identity-5-direction",label:"Perché questo passo conta nella tua settimana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Provare mentalmente è preparazione, non il gesto stesso. La ricerca sull’immaginare comportamenti ha trovato benefici medi sul comportamento, senza un tipo di immaginazione chiaramente migliore. Non dimostra che immaginare i passaggi superi immaginare il risultato, o che meditare sull’identità per un tempo preciso cambi la personalità.","Usa questa preparazione se dalle note emerge una lacuna. Descrivi o immagina il primo passo e un ostacolo probabile. Poi agisci al segnale scelto. Se le immagini creano disagio o non riesci a usarle, scegli le parole o salta il passaggio. Annota la preparazione separatamente. La prova può restare impacciata e il risultato incerto."],example:{title:"Elena scrive una prima frase imperfetta",text:"Prima di lavorare alla relazione lunedì, Elena descrive come inizierà: rileggerà l’ultima riga e aggiungerà una frase, anche poco scorrevole. Prova brevemente il passaggio tenendo gli occhi aperti. Dopo pranzo, al segnale scelto, scrive la frase. È meno fluida di come l’aveva immaginata. Annota la riga scritta separatamente dalla preparazione."}},move:{invitation:"Preparati brevemente, se serve. Salva come esercizio il gesto nella situazione reale.",instructions:["Prova mentalmente il primo passo utile solo se serve.","Fallo al segnale scelto; annota a parte la preparazione."],prompts:[],suggestions:{action:["Aggiungere una frase alla bozza su cui lavoro","Usare una volta la risposta preparata","Completare la parte concreta scelta"],minimum:["Scrivere una frase nella bozza","Usare una risposta al segnale","Finire una parte concreta dell’esercizio"],cue:["Dopo pranzo, quando inizio a scrivere","Nel momento per cui mi sono preparato","Quando arriva il solito segnale"],place:["Nella bozza su cui sto lavorando","Nel solito contesto sicuro per agire"],fallback:["Saltare la prova mentale, scrivere una frase utile","Usare parole, poi provare dopo pranzo","Chiedere aiuto per la competenza mancante"],observation:["Che cosa è successo nella prova concreta","Se è comparso l’ostacolo previsto","Che cosa era soltanto preparazione"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},suggested:{action:"Aggiungere una frase alla bozza su cui lavoro",minimum:"Scrivere una frase nella bozza",minutes:2,cueHint:"Dopo pranzo, quando inizio a scrivere",placeHint:"Nella bozza su cui sto lavorando",obstacleHint:"Continuo a provare mentalmente invece di fare il gesto.",fallbackHint:"Saltare la prova mentale, scrivere una frase utile",observationHint:"Che cosa è successo nella prova concreta"},stopRule:"Evita scene traumatiche. Interrompi le immagini che creano disagio; usa parole, sostegno o una prova diretta sicura.",accessibleAlternative:"Tieni gli occhi aperti o evita le immagini. Per prepararti a parole, scegli “Adatta questo passo” e indica quando agirai."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto e che cosa è successo dopo?"},judgment:{primary:{id:"identity-5-decision",scenario:"Elena conosce il primo punto della relazione e sa come scriverlo. Ha dieci minuti. Immaginare di scrivere con sicurezza ha ritardato gli ultimi due inizi.",question:"Come può passare meglio dalla preparazione all’esercizio?",options:[{id:"identity-5-direct-attempt",text:"Evitare altre prove mentali, scrivere una frase al segnale scelto e annotare dove iniziare è stato difficile.",feedback:"Le note mostrano una preparazione che si allunga, non un primo passo poco chiaro. Scrivere la frase già nota affronta l’ostacolo. Guarda le difficoltà emerse prima di scegliere altra preparazione specifica."},{id:"identity-5-timed-process",text:"Provare mentalmente per due minuti un inizio scorrevole, poi scrivere una frase della relazione prima di finire.",feedback:"Dare un tempo alla prova ne limita la durata e può chiarire un passo nuovo. Elena lo conosce già: la prova mentale ha ritardato due inizi. Scrivere direttamente verifica il problema emerso."},{id:"identity-5-timed-outcome",text:"Immaginare per un minuto di finire la relazione, poi scrivere una frase e annotare che cosa l’ha aiutata.",feedback:"C’è anche un gesto concreto e la ricerca non indica un tipo d’immaginazione migliore. Qui però non emerge poca motivazione. Evitare altre immagini affronta più direttamente la preparazione che continua a rimandare l’azione."}],bestOptionId:"identity-5-direct-attempt"}},carry:{takeaway:"La preparazione utile finisce e lascia spazio a un’occasione reale.",followUp:{questionId:"identity-5-return",question:"Che cosa è stato diverso tra la preparazione e la prova concreta al segnale?",observationPrompt:"Confronta ciò che avevi preparato con l’accaduto al segnale. Puoi anche aver saltato la preparazione.",adjustmentPrompt:"Che cosa vuoi mantenere, cambiare o interrompere alla prossima prova?"}},goDeeper:{sections:[{heading:"Nessun tipo di immaginazione è dimostrato superiore",paragraphs:["Cole e colleghi hanno riunito 94 studi randomizzati, 123 effetti e 5.685 partecipanti [I03]. La simulazione mentale mostrava un effetto complessivo sul comportamento di g = 0,49. Alcune stime erano numericamente più grandi, ma il confronto complessivo tra tipi non era statisticamente significativo. Il sottogruppo che immaginava solo il processo comprendeva appena cinque effetti e restava incerto.","La maggior parte dei campioni era composta da studenti. Molti studi davano poche informazioni sulle possibili distorsioni. La rassegna non dimostra un tipo di immaginazione superiore, un vantaggio dalle prove più lunghe o un cambiamento d’identità da una meditazione di dieci minuti. Questa breve preparazione è una scelta didattica, non il protocollo esaminato.","Scegli parole, immagini o nessuna prova mentale in base alla lacuna concreta. Descrivere un primo passo utile può essere più facile da verificare che immaginare un futuro perfetto. Le note del corso devono comunque riportare che cosa è successo quando quel passo ha incontrato la situazione reale."]},{heading:"Prepara il compito che farai davvero",paragraphs:["La rassegna di Toth e colleghi su 37 studi riguardava prestazioni motorie e compiti [I18]. Riportava un piccolo effetto della pratica mentale, corretto per le distorsioni: r = 0,131. I dati sui compiti motori non dimostrano cambiamenti nella biologia emotiva, guarigione da malattie o trasformazioni generali dell’identità. Preparare un compito non sostituisce istruzioni, materiali ed esercizio concreto.","I piani specifici “se succede questo, farò quello” hanno un sostegno più ampio per gli obiettivi, in verifiche diverse [I01]. Per questa prova ODA, collega un segnale reale al gesto già scelto. Usa la prova mentale solo per chiarire la risposta. Preparare la prima frase e scriverla sono comportamenti diversi. Non dedurre l’uno dall’altro.","Evita scene legate a traumi o ricordi che creano disagio. Puoi tenere gli occhi aperti, descrivere i passaggi senza immagini, farti aiutare o passare direttamente a una prova sicura. Se i preparativi continuano ad allungarsi, riducili invece di aggiungere un altro rituale mattutino."]}],sourceIds:["identity-cole","identity-motor-rehearsal","identity-gollwitzer"]}},{schemaVersion:2,revision:2,id:"identity-6",courseId:"identity",locale:"it",title:"L’occasione salta sempre? Cambia una sola condizione",goal:"Usa le note per cambiare segnale o materiale, poi prova lo stesso gesto utile.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Una routine perfetta non serve se il momento scelto non arriva mai. Oggi verifica una condizione.",reason:{id:"identity-6-reason",label:"Che cosa puoi spostare o riorganizzare per fare spazio a questo gesto?",kind:"text",maxLength:160,optional:!0,suggestions:["Usare un segnale che arriva davvero","Tenere vicino il materiale necessario","Limitare le distrazioni mantenendo i contatti urgenti"]},why:{id:"identity-6-direction",label:"Perché questo passo conta nella tua settimana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Riprendi le prove fatte. Il segnale è arrivato? Avevi il materiale? Anche un piano preciso può fallire se la situazione prevista non si presenta. I piani “se succede questo, farò quello” aiutano in media, ma il segnale deve funzionare nella tua settimana.","La ricerca sulle abitudini collega risposte ripetute a contesti ricorrenti. Cambia una condizione senza decidere che l’ambiente prevalga sulle tue scelte. Mantieni il gesto. Metti il materiale dove inizierai, oppure scegli un evento affidabile. Prova una volta e annota dove la sequenza funziona o si interrompe. Proteggi accessibilità, contatti urgenti e routine necessarie."],example:{title:"A Elena salta la pausa caffè",text:"Elena voleva scrivere dopo il caffè pomeridiano, ma le riunioni facevano saltare la pausa. Cambia solo il segnale: tornando dopo pranzo, aprirà la relazione già pronta sulla scrivania e scriverà una frase. Tiene il telefono a portata di mano per le chiamate della famiglia. Martedì il momento arriva e scrive; la frase ha ancora bisogno di una chiusura migliore."}},move:{invitation:"Cambia una condizione emersa dalle note. Prova lo stesso gesto al nuovo segnale.",instructions:["Scegli un evento principale e uno alternativo che incontri davvero.","Cambia un segnale o un materiale, poi prova il minimo utile."],prompts:[],suggestions:{action:["Scrivere al nuovo segnale di inizio","Esercitarmi con il materiale pronto","Usare la risposta al segnale affidabile"],minimum:["Aggiungere una frase quando arriva il segnale","Completare una parte concreta dell’esercizio","Usare una risposta utile"],cue:["Quando torno dopo pranzo","Quando finisco una routine necessaria","Al prossimo confronto già previsto"],place:["Accanto alla bozza pronta","Nel contesto accessibile per il gesto"],fallback:["Dopo la prossima riunione: una frase alla scrivania","Dettare con gli strumenti disponibili","Mantenere accessibili i contatti urgenti"],observation:["Se è arrivato il nuovo segnale","Se il materiale era pronto","Che cosa ha aiutato o ostacolato"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},suggested:{action:"Scrivere al nuovo segnale di inizio",minimum:"Aggiungere una frase quando arriva il segnale",minutes:2,cueHint:"Quando torno dopo pranzo",placeHint:"Accanto alla bozza pronta",obstacleHint:"Il segnale iniziale spesso non si presenta.",fallbackHint:"Dopo la prossima riunione: una frase alla scrivania",observationHint:"Se è arrivato il nuovo segnale"},stopRule:"Se ci sono pericolo o maltrattamenti, scegli di proteggerti o chiedere sostegno.",accessibleAlternative:"Scrivi, detta, fatti aiutare o scegli un’azione equivalente e accessibile."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto e che cosa è successo dopo?"},judgment:{primary:{id:"identity-6-decision",scenario:"A Elena salta spesso la pausa caffè. Il ritorno dal pranzo avviene comunque e la relazione può restare pronta sulla scrivania.",question:"Quale cambiamento vale la pena provare per primo?",options:[{id:"identity-6-earlier-clock",text:"Mantenere il caffè come segnale, usare un promemoria per proteggere la pausa e scrivere una frase dopo.",feedback:"Un promemoria può aiutare a ricordare, ma non crea la pausa che manca. Le note indicano questo problema. Prova il ritorno dopo pranzo, che avviene davvero, prima di aggiungere un altro avviso."},{id:"identity-6-ready-tea-draft",text:"Mantenere il caffè come segnale e mettere la bozza vicino alla tazzina, poi scrivere una frase dopo la pausa.",feedback:"Spostare il materiale aiuta se la bozza è difficile da raggiungere. Qui è la pausa a saltare, mentre la bozza può già restare pronta. Spostarla non crea il momento mancante."},{id:"identity-6-reliable-event",text:"Usare il ritorno dopo pranzo come segnale, tenere pronta la bozza e provare a scrivere una frase utile.",feedback:"Questo affronta l’interruzione osservata nella sequenza. Il gesto resta uguale e il momento arriva già. Annota se il materiale era pronto e se hai scritto la frase, senza dare il risultato per scontato."}],bestOptionId:"identity-6-reliable-event"}},carry:{takeaway:"Cambia la condizione emersa dalle note. Provala prima di aggiungere altre regole.",followUp:{questionId:"identity-6-availability-return",question:"Il nuovo segnale si è presentato?",observationPrompt:"Il materiale era pronto? Che cosa ha aiutato o ostacolato?",adjustmentPrompt:"Che cosa vuoi mantenere, cambiare o interrompere alla prossima prova?"}},goDeeper:{sections:[{heading:"Preciso non significa automaticamente fattibile",paragraphs:["La meta-analisi di Gollwitzer e Sheeran sostiene in media i piani che collegano situazioni precise e risposte [I01]. Comprendeva obiettivi, campioni e metodi diversi, senza una routine quotidiana ideale. “Dopo il caffè, scrivo” è preciso, ma non rende la pausa un evento affidabile. Devi comunque verificare che il piano sia fattibile e provarlo nella tua settimana.","In questa prova ODA cambi la condizione emersa dalle tue note. Se il segnale non è arrivato, prova un altro evento riconoscibile. Se è arrivato ma mancava il materiale, rendilo disponibile. Se il gesto era troppo grande, riducilo invece di attribuire il problema alla motivazione.","È un adattamento per imparare. Non dimostra che siano necessari tre piani per gli ostacoli o un metodo commerciale per concatenare abitudini. I primi suggerimenti compongono un esempio modificabile. Diventano il tuo impegno solo quando scegli e salvi ciò che va bene nel tuo contesto."]},{heading:"Il contesto aiuta, ma non decide tutto",paragraphs:["Wood e Rünger descrivono risposte ripetute che si sviluppano in contesti ricorrenti [I06]. Le abitudini e le scelte consapevoli possono operare insieme. La rassegna narrativa non dimostra che cambiare ambiente sia sempre superiore all’impegno, né che ogni oggetto determini silenziosamente la tua prossima scelta.","In questa prova, dove metti il materiale è una condizione pratica da verificare. Tieni la relazione vicino alla postazione, oppure rendi disponibile l’ausilio per comunicare nel luogo della conversazione. Considera il compromesso: allontanare il telefono può ridurne l’accesso facile, ma contatti urgenti o ausili per una disabilità possono richiedere un’altra soluzione.","Cambiare una condizione rende più facile capire la prossima nota. Anche scoprire che il nuovo segnale non funziona può essere utile. Conserva il fatto senza chiamare esercizio completato la sola sistemazione. Puoi annotare onestamente la preparazione e riprogrammare o adattare il gesto concreto."]}],sourceIds:["identity-gollwitzer","identity-wood-runger"]}},{schemaVersion:2,revision:2,id:"identity-7",courseId:"identity",locale:"it",title:"Hai saltato giorni? Riprendi senza debiti da recuperare",goal:"Rivedi la stessa prova e scegli una settimana fattibile di esercizio, sostegno o recupero.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"La serie si è interrotta. Il prossimo piano serve alla tua vita o solo a sistemare il numero?",reason:{id:"identity-7-reason",label:"Questa prova merita ancora spazio nella tua settimana?",kind:"text",maxLength:160,optional:!0,suggestions:["Mantenere la parte utile","Ridurre l’impegno alle mie energie","Recuperare senza compensare i giorni saltati"]},why:{id:"identity-7-direction",label:"Perché questo passo conta nella tua settimana?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Il famoso numero di 66 giorni stimava quanto un comportamento diventava automatico. Non indicava quando le persone finivano di cambiare. Le stime variavano molto e alcune andavano oltre il periodo osservato. Non dicono quando il tuo gesto dovrebbe diventare facile.","Riguarda la stessa prova: gesto utile, segnale, tentativi fatti e condizione da sistemare. Scegli un’occasione adatta alle tue energie. Ripeti, riduci, chiedi aiuto, riposa o interrompi un obiettivo che non ti serve più. Non aggiungere rituali o lavoro da recuperare per dimostrare che hai finito il corso."],example:{title:"Elena riprende con meno impegno",text:"Dopo una malattia, Elena non ha provato a lavorare alla relazione per tre giorni. Riguarda le frasi scritte e il momento dopo pranzo che funzionava. È ancora esausta: oggi recupera e domani farà il punto. Solo allora deciderà se una frase è fattibile. Annota la pausa senza riscrivere i giorni saltati o promettere una sessione per compensarli."}},move:{invitation:"Rivedi la stessa prova. Scegli un’occasione adatta, oppure salva una pausa e una data per fare il punto.",instructions:["Mantieni il gesto utile; cambia solo ciò che le note giustificano.","Scegli quantità e segnale della prossima settimana senza debiti da recuperare."],prompts:[],suggestions:{action:["Ripetere il mio minimo utile","Provare una parte più piccola ma utile","Chiedere sostegno per la mia prova"],minimum:["Scrivere una frase da usare","Completare una parte accessibile dell’esercizio","Fare una richiesta concreta di sostegno"],cue:["Quando rientro dopo pranzo e posso provare","Quando posso provare in sicurezza","Al confronto scelto per chiedere sostegno"],place:["Nel solito contesto accessibile","In una conversazione sicura di sostegno"],fallback:["Fare una pausa e scegliere quando tornare","Ridurre la parte concreta da fare","Chiedere aiuto per il vincolo presente"],observation:["Se il gesto serviva ancora al mio obiettivo","Che cosa era adatto alle mie energie","Quale condizione ha aiutato la ripresa"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},suggested:{action:"Ripetere il mio minimo utile",minimum:"Scrivere una frase da usare",minutes:2,cueHint:"Quando rientro dopo pranzo e posso provare",placeHint:"Nel solito contesto accessibile",obstacleHint:"Vorrei compensare i giorni in cui non ho provato.",fallbackHint:"Fare una pausa e scegliere quando tornare",observationHint:"Se il gesto serviva ancora al mio obiettivo"},stopRule:"Se ci sono pericolo o maltrattamenti, scegli di proteggerti o chiedere sostegno.",accessibleAlternative:"Scrivi, detta, fatti aiutare o scegli un’azione equivalente e accessibile."},result:{question:"Hai fatto il minimo che avevi scelto?",observationPrompt:"Che cosa hai fatto e che cosa è successo dopo?"},judgment:{primary:{id:"identity-7-decision",scenario:"Elena ha saltato l’esercizio mentre era malata ed è ancora esausta. Le note mostrano che il momento dopo pranzo funzionava.",question:"Quale piano rispetta i fatti e le sue energie?",options:[{id:"identity-7-preserve-volume",text:"Usare oggi il segnale abituale e scrivere la solita quantità più lentamente, per mantenere intatta la routine.",feedback:"Un segnale familiare può aiutare quando tornano le energie, ma non prevale sulla stanchezza estrema. Le note sostengono il segnale, non la quantità di oggi. Recuperare e rivalutare a una data scelta può essere appropriato."},{id:"identity-7-reassess-capacity",text:"Riposare oggi, scegliere quando valutare le energie e riprendere un gesto utile più piccolo quando sarà fattibile.",feedback:"Così conserva la prova utile senza chiamare fallimento il recupero. Programma una decisione, senza fingere di aver scritto. La prossima prova dovrà corrispondere alle energie che avrà allora."},{id:"identity-7-catch-up",text:"Spostare il lavoro saltato in una sessione più lunga nel fine settimana, per raggiungere il totale iniziale.",feedback:"Una sessione successiva può rispondere a un bisogno reale. Le prove saltate non creano però un obbligo scientifico di compensare. Un impegno maggiore può ostacolare il recupero: valuta le energie prima di aumentarlo."}],bestOptionId:"identity-7-reassess-capacity"}},carry:{takeaway:"Mantieni la prova utile, rivedi l’impegno e riprendi senza una scadenza per diventare un’altra persona.",followUp:{questionId:"identity-7-return",question:"La ripresa era adatta alle tue energie e all’obiettivo? Il prossimo piano va cambiato?",observationPrompt:"Che cosa era adatto alle tue energie e al tuo obiettivo? Che cosa va cambiato?",adjustmentPrompt:"Che cosa vuoi mantenere, cambiare o interrompere alla prossima prova?"}},goDeeper:{sections:[{heading:"Il numero famoso stimava l’automaticità",paragraphs:["Lally e colleghi hanno seguito 96 volontari per 84 giorni, su comportamenti scelti di alimentazione, bevande o attività fisica [I04]. Avevano 82 casi con dati sufficienti, 62 modelli e 39 con buona corrispondenza ai dati. In questi ultimi, il tempo stimato per arrivare al 95% del livello stabile di automaticità aveva mediana 66 giorni e intervallo 18-254 giorni.","I tempi più lunghi erano estrapolati oltre l’osservazione. Lo studio non ha visto tutti “completare un’abitudine”, misurato una personalità nuova o verificato una regola sui due giorni consecutivi saltati. Nell’analisi, perdere un’occasione non alterava sostanzialmente la formazione. Da questo non si può ricavare una regola universale per riprendere dopo interruzioni più lunghe.","Una rassegna successiva su 20 studi di comportamenti per la salute confermava un’ampia variabilità [I05]. Solo quattro riportavano tempi di formazione; 11 avevano alto rischio di distorsione. Nessuna delle due fonti dice quando scrivere, ascoltare o un altro gesto scelto in ODA debba diventare automatico."]},{heading:"Riunisci i fatti, senza aggiungere un rituale",paragraphs:["Harkin e colleghi hanno esaminato interventi che aumentavano il monitoraggio dei progressi in 138 studi randomizzati [I02]. Il raggiungimento medio degli obiettivi migliorava, con una stima più piccola dopo la correzione per le distorsioni. Metodi e obiettivi erano diversi. La rassegna non indica come formato ottimale una revisione settimanale di quindici minuti, una serie continua o una lettera al proprio io futuro.","Fare il punto nel corso è una scelta di ODA. Leggi le note della stessa prova, distingui tentativi concreti, piani e pause, e individua la condizione da mantenere. Un piano futuro non dimostra che hai già svolto l’azione. Se mancano note, ciò che è successo resta sconosciuto finché non lo riferisci.","Scegli quantità e segnale riconoscibile per la prossima settimana solo se la prova serve ancora al tuo obiettivo. Sostegno, recupero, un limite o l’interruzione possono essere risposte deliberate. Chiamale con precisione. Per riprendere con criterio non servono una nuova frase sull’identità, una sessione più lunga o compensazioni per i giorni saltati."]}],sourceIds:["identity-lally","identity-habit-times","identity-harkin"]}}];function i(e,t,n){const o=e.judgment.primary;return{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,practice:[e.move.invitation,"Prova il minimo scelto al tuo segnale di inizio, oppure registra una pausa.","Annota che cosa è successo. Alla data scelta, torna a valutare la stessa prova."],reflection:e.direction.reason.label,question:o.scenario+" "+o.question,options:o.options.map(r=>r.text),correct:t,feedback:o.options[t].feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,deeper:e.goDeeper.sections,example:e.idea.example,photo:n}}const l={id:"identity",title:"Ci ricaschi? Cambia una risposta",subtitle:"Sette lezioni per trovare un segnale ricorrente, provare una risposta utile e migliorarla da ciò che succede.",description:"Scegli uno schema che toglie spazio a qualcosa che vuoi. Prova una risposta utile, annota il risultato e adatta segnale, preparazione o sostegno alla tua vita.",outcome:"Un gesto che conta, un segnale verificato e un piano onesto per riprendere nella tua settimana.",scope:"Per adulti che cercano un modo quotidiano per cambiare uno schema familiare di pensieri, emozioni o risposte. Il corso prende spunto da Joe Dispenza e James Clear e chiarisce quali loro idee la ricerca sostiene e quali no. Non è terapia né un trattamento per depressione, ansia, traumi o malattie. Se stai facendo fatica, parla con un professionista sanitario. In una crisi, chiama i servizi di emergenza locali.",photo:{id:"1611569518992-0927098278b7",alt:"Una donna cammina da sola su una strada sterrata tra alberi verdi"},lang:"it",lessons:[i(a[0],1,{id:"1519087630026-63fb0dab69bb",alt:"Una donna guarda il suo riflesso in uno specchio a parete"}),i(a[1],2,{id:"1762126242240-cafa01fb1351",alt:"Una persona in poltrona guarda fuori da una finestra mentre piove"}),i(a[2],0,{id:"1626257690705-8d62125575b0",alt:"Un uomo con una giacca scura cammina di giorno in una via pedonale"}),i(a[3],1,{id:"1787154604447-4a62ed6654e3",alt:"Una donna con hijab scuro e abiti sportivi corre lungo una strada cittadina"}),i(a[4],0,{id:"1600618528240-fb9fc964b853",alt:"Una donna medita su una terrazza di legno al tramonto"}),i(a[5],2,{id:"1675762647949-1b25f669a687",alt:"Un paio di scarpe bianche su un pavimento di legno"}),i(a[6],1,{id:"1760715160644-7f5939675b68",alt:"Escursionisti camminano su un sentiero in un prato dorato"})]},c=Object.freeze(Object.defineProperty({__proto__:null,COURSE:l,LESSONS_V2:a,SOURCES:s},Symbol.toStringTag,{value:"Module"}));export{c as i};
